function e(){let a=()=>(13+Math.floor(Math.random()*3)).toString(16);return`#${a()}${a()}${a()}${a()}${a()}${a()}`.toUpperCase()}var o=[{categoria:"System",shortDescription:"Gerencie arquivos do sistema com seguran\xE7a e agilidade. Navegue entre diret\xF3rios, realize uploads e mantenha a organiza\xE7\xE3o dos dados corporativos essenciais.",description:"O m\xF3dulo Arquivos oferece uma solu\xE7\xE3o robusta para o gerenciamento centralizado de dados dentro do servidor. Com ele, administradores e usu\xE1rios autorizados podem navegar pela estrutura de diret\xF3rios, visualizar pr\xE9vias de documentos e executar opera\xE7\xF5es de manuten\xE7\xE3o com facilidade. A ferramenta suporta upload em lote, controle de versionamento b\xE1sico e permiss\xF5es granulares de acesso, garantindo que a informa\xE7\xE3o sens\xEDvel permane\xE7a protegida. \xC9 a ferramenta ideal para manter a integridade dos dados organizacionais, permitindo auditorias r\xE1pidas, organiza\xE7\xE3o eficiente de logs, backups e m\xEDdias do sistema, tudo atrav\xE9s de uma interface web intuitiva.",color:e(),url:"/Arquivos",name:"Arquivos",roles:["ADMIN","MASTER"],icon:"files",type:"svg"},{shortDescription:"Centralize os dados de clientes, fornecedores e parceiros. Mantenha as informa\xE7\xF5es vitais da sua rede de contatos sempre atualizadas, organizadas e acess\xEDveis.",description:"O m\xF3dulo Cadastros atua como a espinha dorsal da informa\xE7\xE3o corporativa. Ele permite o registro detalhado e a manuten\xE7\xE3o de dados de todas as entidades que interagem com a empresa, incluindo clientes, fornecedores, parceiros e colaboradores. Com recursos avan\xE7ados de valida\xE7\xE3o de dados e campos personalizados, o sistema evita duplicidades e garante a consist\xEAncia das informa\xE7\xF5es. Al\xE9m disso, integra-se nativamente com outros m\xF3dulos como Vendas e Financeiro, automatizando o preenchimento de documentos e facilitando o fluxo de trabalho operacional. A gest\xE3o eficiente destes cadastros \xE9 fundamental para estrat\xE9gias de CRM e para a conformidade fiscal da organiza\xE7\xE3o.",color:e(),url:"/Cadastros",name:"Cadastros",roles:["MASTER"],icon:"cadastros",type:"svg"},{shortDescription:"Editor de c\xF3digo-fonte completo integrado ao navegador. Ferramentas avan\xE7adas para programadores que buscam agilidade, controle de vers\xE3o e manuten\xE7\xE3o de scripts.",description:'O Codex \xE9 um ambiente de desenvolvimento integrado (IDE) projetado para oferecer uma experi\xEAncia de codifica\xE7\xE3o completa sem sair do portal. Suportando m\xFAltiplas linguagens de programa\xE7\xE3o com destaque de sintaxe, autocompletar inteligente e ferramentas de linting, ele permite que desenvolvedores realizem ajustes r\xE1pidos ou construam m\xF3dulos complexos. A plataforma inclui hist\xF3rico de revis\xF5es, facilitando o rollback de altera\xE7\xF5es, e oferece um ambiente seguro ("sandbox") para testar snippets de c\xF3digo antes da implanta\xE7\xE3o em produ\xE7\xE3o. \xC9 a ferramenta definitiva para a equipe t\xE9cnica realizar a manuten\xE7\xE3o, corre\xE7\xE3o de bugs e expans\xE3o das capacidades do sistema em tempo real.',color:e(),url:"/Codex",name:"Codex",roles:["MASTER"],icon:"codex",type:"svg"},{shortDescription:"Conjunto de utilit\xE1rios essenciais para an\xE1lise e depura\xE7\xE3o do sistema. Monitore performance, inspecione requisi\xE7\xF5es e otimize o funcionamento da aplica\xE7\xE3o.",description:"O DevTools \xE9 um painel de instrumenta\xE7\xE3o avan\xE7ada destinado \xE0 equipe de engenharia e suporte t\xE9cnico. Ele fornece visibilidade profunda sobre o comportamento da aplica\xE7\xE3o, permitindo monitorar o consumo de recursos, analisar logs de erro em tempo real e inspecionar o tr\xE1fego de rede das APIs internas. Com ferramentas para testar endpoints, validar estruturas de dados JSON e simular diferentes condi\xE7\xF5es de ambiente, o DevTools \xE9 indispens\xE1vel para diagn\xF3sticos precisos. Ele acelera o ciclo de resolu\xE7\xE3o de problemas e garante que a performance do portal se mantenha nos n\xEDveis mais elevados, identificando gargalos antes que afetem o usu\xE1rio final.",color:e(),url:"/DevTools",name:"DevTools",roles:["MASTER"],icon:"dev-tools",type:"svg"},{shortDescription:"Crie interfaces e prot\xF3tipos de alta fidelidade com facilidade. Uma ferramenta de design focada na experi\xEAncia do usu\xE1rio e na agilidade de desenvolvimento visual.",description:"O Dynamic XD \xE9 uma plataforma de design e prototipa\xE7\xE3o voltada para a cria\xE7\xE3o \xE1gil de interfaces de usu\xE1rio. Ele permite que designers e desenvolvedores colaborem na constru\xE7\xE3o de layouts responsivos, definindo fluxos de navega\xE7\xE3o e intera\xE7\xF5es visuais sem a necessidade de c\xF3digo complexo inicial. Com uma biblioteca de componentes pr\xE9-constru\xEDdos e suporte a drag-and-drop, \xE9 poss\xEDvel transformar ideias abstratas em prot\xF3tipos funcionais rapidamente. A ferramenta facilita a valida\xE7\xE3o de conceitos com stakeholders e gera automaticamente os estilos CSS e especifica\xE7\xF5es t\xE9cnicas necess\xE1rias para a implementa\xE7\xE3o final, reduzindo drasticamente o tempo entre o design e o produto final.",color:e(),url:"/Dynamic",name:"Dynamic XD",roles:["MASTER"],icon:"dynamic",type:"svg"},{shortDescription:"Controle total sobre o fluxo de caixa, contas a pagar e receber. Uma su\xEDte completa para a gest\xE3o cont\xE1bil e financeira, garantindo sa\xFAde econ\xF4mica para o neg\xF3cio.",description:"O m\xF3dulo Financeiro \xE9 o centro de comando para a sa\xFAde econ\xF4mica da organiza\xE7\xE3o. Ele oferece ferramentas abrangentes para o gerenciamento de contas a pagar e receber, concilia\xE7\xE3o banc\xE1ria, fluxo de caixa e emiss\xE3o de notas fiscais. Com dashboards intuitivos, gestores podem visualizar a performance financeira em tempo real, gerar relat\xF3rios de DRE e balancetes com poucos cliques. O sistema permite a automa\xE7\xE3o de cobran\xE7as recorrentes, o controle de centros de custo e a integra\xE7\xE3o direta com os gateways de pagamento. Projetado para garantir conformidade fiscal e transpar\xEAncia, ele fornece os dados necess\xE1rios para tomadas de decis\xE3o estrat\xE9gicas e planejamento or\xE7ament\xE1rio seguro.",color:e(),url:"/Financeiro",name:"Financeiro",roles:["MASTER"],icon:"financeiro",type:"svg"},{shortDescription:"Construa formul\xE1rios din\xE2micos para coleta de dados. Personalize campos, valida\xE7\xF5es e fluxos de resposta para atender a qualquer necessidade de pesquisa ou cadastro.",description:"A ferramenta Formul\xE1rios permite a cria\xE7\xE3o r\xE1pida e flex\xEDvel de interfaces para coleta de dados. Seja para pesquisas de satisfa\xE7\xE3o, inscri\xE7\xF5es em eventos ou processos de auditoria interna, o sistema oferece um construtor visual intuitivo onde \xE9 poss\xEDvel arrastar e soltar diversos tipos de campos. Com suporte a l\xF3gica condicional, as perguntas podem se adaptar com base nas respostas anteriores do usu\xE1rio. Todos os dados coletados s\xE3o automaticamente tabulados e podem ser exportados para an\xE1lise ou integrados a outros sistemas via webhooks. \xC9 a solu\xE7\xE3o ideal para digitalizar processos baseados em papel e padronizar a entrada de informa\xE7\xF5es em toda a empresa.",color:e(),url:"/Formularios",name:"Formularios",roles:["USER","MASTER"],icon:"formularios",type:"svg"},{shortDescription:"Painel executivo com indicadores chave de desempenho (KPIs). Visualize m\xE9tricas estrat\xE9gicas em tempo real para embasar decis\xF5es gerenciais de alto n\xEDvel.",description:"O m\xF3dulo Gerencial transforma dados brutos em intelig\xEAncia de neg\xF3cios acion\xE1vel. Atrav\xE9s de dashboards personaliz\xE1veis e visualiza\xE7\xF5es de dados interativas, ele agrega informa\xE7\xF5es de todos os outros setores \u2014 vendas, financeiro, opera\xE7\xF5es \u2014 para oferecer uma vis\xE3o hol\xEDstica da empresa. Gestores podem acompanhar KPIs em tempo real, identificar tend\xEAncias de mercado e monitorar o cumprimento de metas organizacionais. Com recursos de drill-down, \xE9 poss\xEDvel investigar a causa raiz de varia\xE7\xF5es nos n\xFAmeros, indo do macro ao micro detalhe. Esta ferramenta \xE9 essencial para a governan\xE7a corporativa, garantindo que a lideran\xE7a tenha as informa\xE7\xF5es precisas para pilotar o neg\xF3cio.",color:e(),url:"/Gerencial",name:"Gerencial",roles:["MASTER"],icon:"gerencial",type:"svg"},{shortDescription:"Acesse uma vasta biblioteca de \xEDcones vetoriais padronizados. Recursos visuais prontos para uso em projetos de design, desenvolvimento e documenta\xE7\xE3o.",description:"O m\xF3dulo Icons serve como um reposit\xF3rio centralizado de ativos visuais da empresa. Ele disponibiliza uma extensa cole\xE7\xE3o de \xEDcones vetoriais (SVG) e fontes de \xEDcones, todos padronizados de acordo com a identidade visual da marca. Desenvolvedores e designers podem buscar, visualizar e copiar c\xF3digos de implementa\xE7\xE3o ou baixar arquivos em diversos formatos e tamanhos. A biblioteca \xE9 constantemente atualizada para incluir novas representa\xE7\xF5es gr\xE1ficas necess\xE1rias para os produtos digitais. Isso garante a consist\xEAncia visual em todas as aplica\xE7\xF5es e materiais de comunica\xE7\xE3o, agilizando o trabalho das equipes de front-end e UX/UI ao eliminar a necessidade de desenhar \xEDcones do zero.",color:e(),url:"/Icons",name:"Icons",roles:["MASTER"],icon:"icones",type:"svg"},{shortDescription:"Ambiente dedicado ao aprendizado profundo e onboarding. Trilhas de conhecimento estruturadas para acelerar a adapta\xE7\xE3o e o desenvolvimento de novas compet\xEAncias.",description:"A plataforma Imers\xE3o foi desenhada para facilitar a transfer\xEAncia de conhecimento t\xE1cito e expl\xEDcito dentro da organiza\xE7\xE3o. Ideal para o onboarding de novos colaboradores ou para a reciclagem de equipes, ela organiza o conte\xFAdo em trilhas de aprendizado interativas e sequenciais. O sistema suporta diversos formatos de m\xEDdia, incluindo v\xEDdeos, artigos e quizzes de verifica\xE7\xE3o de conhecimento. Ao focar na experi\xEAncia do usu\xE1rio, a Imers\xE3o garante maior engajamento e reten\xE7\xE3o de informa\xE7\xF5es. Gestores podem acompanhar o progresso individual de cada membro, identificando lacunas de compet\xEAncia e garantindo que todos estejam alinhados com a cultura e os processos da empresa.",color:e(),url:"/Imersao",name:"Imersao",roles:["MASTER"],icon:"imersao",type:"svg"},{shortDescription:"Gerenciamento centralizado da infraestrutura de TI. Monitore servidores, servi\xE7os em nuvem e recursos de rede para garantir a disponibilidade cont\xEDnua do sistema.",description:"O m\xF3dulo Infra oferece controle total sobre os ativos tecnol\xF3gicos que sustentam as opera\xE7\xF5es da empresa. Ele permite o monitoramento em tempo real da sa\xFAde dos servidores, balanceadores de carga, bancos de dados e servi\xE7os de nuvem. Com alertas configur\xE1veis para anomalias de CPU, mem\xF3ria ou lat\xEAncia de rede, a equipe de DevOps pode agir proativamente antes que incidentes ocorram. Al\xE9m do monitoramento, a ferramenta facilita o gerenciamento de configura\xE7\xF5es, deploys automatizados e a escalabilidade dos recursos. \xC9 o painel de controle indispens\xE1vel para garantir a alta disponibilidade (uptime), a seguran\xE7a perimetral e a efici\xEAncia operacional de toda a infraestrutura tecnol\xF3gica.",color:e(),url:"/Infra",name:"Infra",roles:["MASTER"],icon:"infra",type:"svg"},{shortDescription:"Gerencie a instala\xE7\xE3o e ativa\xE7\xE3o de novos m\xF3dulos e funcionalidades. Um assistente completo para configurar e implantar recursos adicionais no seu ambiente.",description:"O m\xF3dulo Instala\xE7\xE3o simplifica o processo de expans\xE3o e atualiza\xE7\xE3o do ecossistema de software. Ele atua como um gerenciador de pacotes e assistente de configura\xE7\xE3o (wizard), guiando o administrador atrav\xE9s das etapas necess\xE1rias para ativar novas funcionalidades ou integrar servi\xE7os de terceiros. O sistema verifica automaticamente depend\xEAncias, compatibilidade de vers\xF5es e pr\xE9-requisitos de sistema antes de executar qualquer altera\xE7\xE3o. Al\xE9m disso, mant\xE9m um hist\xF3rico detalhado de todas as instala\xE7\xF5es e atualiza\xE7\xF5es realizadas, facilitando a auditoria e a manuten\xE7\xE3o. Com ele, a implementa\xE7\xE3o de novos recursos torna-se um processo seguro, padronizado e livre de erros manuais.",color:e(),url:"/Instalacao",name:"Instalacao",roles:["MASTER"],icon:"instalacao",type:"svg"},{shortDescription:"Desenvolva aplica\xE7\xF5es poderosas com o m\xEDnimo de programa\xE7\xE3o manual. Uma plataforma \xE1gil que democratiza a cria\xE7\xE3o de software atrav\xE9s de interfaces visuais.",description:'A plataforma LowCode revoluciona a forma como solu\xE7\xF5es internas s\xE3o constru\xEDdas, permitindo que usu\xE1rios com pouco conhecimento t\xE9cnico criem aplica\xE7\xF5es funcionais. Utilizando uma interface visual de arrastar e soltar, \xE9 poss\xEDvel modelar bancos de dados, desenhar interfaces e definir l\xF3gicas de neg\xF3cio complexas sem escrever milhares de linhas de c\xF3digo. O sistema abstrai a complexidade t\xE9cnica, cuidando da seguran\xE7a e da escalabilidade em segundo plano. Isso reduz drasticamente o "time-to-market" de novas ferramentas internas e empodera as \xE1reas de neg\xF3cio a resolverem seus pr\xF3prios problemas de automa\xE7\xE3o, liberando a equipe de desenvolvimento para focar em desafios estruturais.',color:e(),url:"/LowCode",name:"LowCode",roles:["MASTER"],icon:"low-code",type:"svg"},{shortDescription:"Hub central de comunica\xE7\xE3o interna e externa. Envie notifica\xE7\xF5es, gerencie chats e mantenha o hist\xF3rico de conversas seguro e organizado em um s\xF3 lugar.",description:"O m\xF3dulo Mensagens centraliza toda a comunica\xE7\xE3o da plataforma, eliminando a dispers\xE3o de informa\xE7\xF5es em canais n\xE3o oficiais. Ele suporta mensagens diretas entre usu\xE1rios, grupos de trabalho e notifica\xE7\xF5es broadcast para toda a organiza\xE7\xE3o. Com recursos de criptografia e arquivamento seguro, garante a privacidade e a conformidade das trocas de informa\xE7\xF5es corporativas. Al\xE9m da comunica\xE7\xE3o humana, o sistema serve como inbox para alertas autom\xE1ticos do sistema, informando sobre tarefas pendentes, aprova\xE7\xF5es necess\xE1rias ou atualiza\xE7\xF5es de status. A integra\xE7\xE3o com e-mail e push notifications garante que nenhuma mensagem cr\xEDtica seja perdida, mantendo as equipes conectadas e alinhadas.",color:e(),url:"/Mensagens",name:"Mensagens",roles:["USER","MASTER"],icon:"mensagens",type:"svg"},{shortDescription:"Ferramentas para maximizar a produtividade pessoal e profissional. Agendas, listas de tarefas e anota\xE7\xF5es integradas para manter o foco no que realmente importa.",description:"O m\xF3dulo Organiza\xE7\xE3o \xE9 uma su\xEDte de produtividade desenhada para otimizar a gest\xE3o do tempo e das atividades di\xE1rias. Ele combina funcionalidades de calend\xE1rio compartilhado, listas de tarefas (to-do lists) hier\xE1rquicas e um sistema de anota\xE7\xF5es ricas. Usu\xE1rios podem agendar reuni\xF5es verificando a disponibilidade dos colegas, definir lembretes para prazos importantes e categorizar suas demandas por prioridade ou projeto. A integra\xE7\xE3o com outros m\xF3dulos permite transformar pend\xEAncias de projetos ou vendas diretamente em tarefas pessoais. Focado na efici\xEAncia, este m\xF3dulo ajuda a reduzir a carga cognitiva, garantindo que profissionais e equipes mantenham o foco na execu\xE7\xE3o e nos resultados.",color:e(),url:"/Organizacao",name:"Organizacao",roles:["MASTER"],icon:"organizacao",type:"svg"},{shortDescription:"Cat\xE1logo completo para gest\xE3o de produtos e servi\xE7os. Controle estoque, varia\xE7\xF5es, pre\xE7os e especifica\xE7\xF5es t\xE9cnicas com detalhamento e precis\xE3o.",description:"O m\xF3dulo Produtos \xE9 a base para as opera\xE7\xF5es comerciais e de estoque. Ele permite o cadastro exaustivo de itens, suportando m\xFAltiplas variantes (como cor, tamanho, voltagem), imagens em alta resolu\xE7\xE3o, fichas t\xE9cnicas e c\xF3digos de barras (EAN/UPC). O sistema gerencia n\xEDveis de estoque em m\xFAltiplos dep\xF3sitos, alerta sobre pontos de reposi\xE7\xE3o e controla a movimenta\xE7\xE3o de entrada e sa\xEDda de mercadorias. Al\xE9m disso, permite a gest\xE3o de listas de pre\xE7os diferenciadas e regras de tributa\xE7\xE3o. Essencial para empresas de varejo, distribui\xE7\xE3o ou manufatura, ele garante que o portf\xF3lio de ofertas esteja sempre organizado, atualizado e pronto para ser comercializado nos canais de venda.",color:e(),url:"/Produtos",name:"Produtos",roles:["MASTER"],icon:"produtos",type:"svg"},{shortDescription:"\xC1rea pessoal para gest\xE3o de conta e prefer\xEAncias. Atualize dados cadastrais, configure seguran\xE7a, notifica\xE7\xF5es e personalize sua experi\xEAncia no sistema.",description:"A \xE1rea de Profile \xE9 o espa\xE7o onde cada usu\xE1rio det\xE9m controle sobre sua identidade e experi\xEAncia dentro da plataforma. Aqui, \xE9 poss\xEDvel atualizar informa\xE7\xF5es pessoais, gerenciar credenciais de acesso, alterar senhas e configurar autentica\xE7\xE3o de dois fatores (2FA) para maior seguran\xE7a. O m\xF3dulo tamb\xE9m permite a personaliza\xE7\xE3o da interface, como escolha de temas (claro/escuro) e prefer\xEAncias de idioma. Al\xE9m disso, o usu\xE1rio pode definir granularmente suas prefer\xEAncias de notifica\xE7\xE3o, escolhendo quais alertas deseja receber e por quais canais. \xC9 um componente vital para garantir a privacidade, a seguran\xE7a individual e o conforto no uso di\xE1rio das ferramentas corporativas.",color:e(),url:"/Profile",name:"Profile",roles:["MASTER"],icon:"perfil",type:"svg"},{shortDescription:"Gest\xE3o completa do ciclo de vida de projetos. Planeje cronogramas, delegue tarefas e acompanhe o progresso das entregas com metodologias \xE1geis ou tradicionais.",description:"O m\xF3dulo Projetos oferece uma estrutura robusta para o gerenciamento de iniciativas complexas, do planejamento \xE0 entrega final. Compat\xEDvel com metodologias \xE1geis (Kanban, Scrum) e tradicionais (Gantt), ele permite que gestores definam escopos, aloquem recursos e estipulem prazos realistas. A ferramenta facilita a colabora\xE7\xE3o da equipe atrav\xE9s de coment\xE1rios em tarefas, compartilhamento de arquivos e atualiza\xE7\xF5es de status em tempo real. Relat\xF3rios de progresso e an\xE1lise de burn-down ajudam a identificar gargalos e desvios de cronograma precocemente. \xC9 a solu\xE7\xE3o ideal para manter equipes multidisciplinares alinhadas, garantindo que os objetivos estrat\xE9gicos sejam atingidos dentro do prazo e do or\xE7amento.",color:e(),url:"/Projetos",name:"Projetos",roles:["MASTER"],icon:"projetos",type:"svg"},{shortDescription:"Otimize a presen\xE7a digital com ferramentas de SEO avan\xE7adas. Analise palavras-chave, monitore rankings e melhore a visibilidade do seu conte\xFAdo nos motores de busca.",description:"O m\xF3dulo SEO \xE9 um conjunto de ferramentas anal\xEDticas e operacionais focado na otimiza\xE7\xE3o para motores de busca. Ele permite auditar p\xE1ginas do site em busca de falhas t\xE9cnicas, analisar a densidade de palavras-chave e monitorar o ranking de termos estrat\xE9gicos ao longo do tempo. O sistema oferece sugest\xF5es de melhoria para meta-tags, estrutura de links internos e performance de carregamento (Core Web Vitals). Al\xE9m disso, permite a an\xE1lise da concorr\xEAncia e o rastreamento de backlinks. Ideal para equipes de marketing e conte\xFAdo, este m\xF3dulo fornece os insights necess\xE1rios para aumentar o tr\xE1fego org\xE2nico, melhorar a autoridade do dom\xEDnio e garantir que a marca seja encontrada pelo seu p\xFAblico-alvo.",color:e(),url:"/SEO",name:"SEO",roles:["MASTER"],icon:"seo",type:"svg"},{shortDescription:"Crie e manipule experi\xEAncias gr\xE1ficas 3D interativas na web. Ferramentas poderosas baseadas em WebGL para visualiza\xE7\xE3o de produtos, dados e ambientes virtuais.",description:"O m\xF3dulo Threejs integra capacidades avan\xE7adas de computa\xE7\xE3o gr\xE1fica 3D diretamente ao navegador. Baseado na biblioteca WebGL, ele permite a importa\xE7\xE3o, cria\xE7\xE3o e manipula\xE7\xE3o de modelos tridimensionais complexos com texturas, ilumina\xE7\xE3o e f\xEDsica realista. \xC9 a ferramenta perfeita para desenvolver configuradores de produtos imersivos, visualiza\xE7\xF5es de dados espaciais, g\xEAmeos digitais ou experi\xEAncias de gamifica\xE7\xE3o. O editor visual facilita o ajuste de cenas e c\xE2meras, enquanto a API robusta permite intera\xE7\xF5es program\xE1ticas profundas. Com ele, a fronteira entre o conte\xFAdo web est\xE1tico e experi\xEAncias imersivas \xE9 quebrada, oferecendo um diferencial visual e funcional significativo para as aplica\xE7\xF5es.",color:e(),url:"/Threejs",name:"Threejs",roles:["MASTER"],icon:"threejs",type:"svg"},{shortDescription:"Plataforma completa de educa\xE7\xE3o corporativa. Crie cursos, distribua conte\xFAdo e avalie o desempenho dos colaboradores para promover o crescimento cont\xEDnuo.",description:"O m\xF3dulo Treinamento funciona como uma Universidade Corporativa digital (LMS). Ele permite a cria\xE7\xE3o e gest\xE3o de cat\xE1logos de cursos, desde treinamentos de compliance obrigat\xF3rios at\xE9 workshops de desenvolvimento de soft skills. Suportando v\xEDdeos, apresenta\xE7\xF5es interativas e avalia\xE7\xF5es, o sistema gerencia matr\xEDculas, frequ\xEAncias e emiss\xE3o de certificados automaticamente. Relat\xF3rios detalhados permitem ao RH medir o ROI dos treinamentos e identificar talentos internos. A plataforma promove uma cultura de aprendizado cont\xEDnuo, garantindo que a for\xE7a de trabalho esteja sempre atualizada com as melhores pr\xE1ticas de mercado e as inova\xE7\xF5es da empresa, aumentando a competitividade e a reten\xE7\xE3o de talentos.",color:e(),url:"/Treinamento",name:"Treinamento",roles:["MASTER"],icon:"treinamento",type:"svg"},{shortDescription:"Acelere o ciclo de vendas e gerencie pedidos com efici\xEAncia. Do or\xE7amento ao faturamento, tenha controle total sobre a performance comercial da sua equipe.",description:"O m\xF3dulo Vendas \xE9 o motor comercial da empresa, projetado para agilizar o fechamento de neg\xF3cios. Ele permite a cria\xE7\xE3o r\xE1pida de or\xE7amentos, pedidos de venda e contratos, com c\xE1lculo autom\xE1tico de impostos e descontos baseados em regras pr\xE9-definidas. Integrado ao estoque e ao financeiro, garante que apenas produtos dispon\xEDveis sejam vendidos e que o faturamento ocorra sem atritos. O sistema oferece funis de vendas visuais para acompanhar oportunidades em cada est\xE1gio, al\xE9m de relat\xF3rios de desempenho por vendedor, regi\xE3o ou produto. \xC9 a ferramenta essencial para transformar leads em clientes fi\xE9is, maximizar a receita e dar visibilidade total sobre as metas comerciais.",color:e(),url:"/Vendas",name:"Vendas",roles:["MASTER"],icon:"vendas",type:"svg"},{shortDescription:"Gerencie o relacionamento com seus clientes de forma estrat\xE9gica. Hist\xF3rico de intera\xE7\xF5es, segmenta\xE7\xE3o e ferramentas para fideliza\xE7\xE3o em uma \xFAnica plataforma.",description:"O CRM (Customer Relationship Management) \xE9 focado em construir e manter relacionamentos duradouros com a base de clientes. Ele centraliza todo o hist\xF3rico de intera\xE7\xF5es \u2014 chamadas, emails, reuni\xF5es e compras passadas \u2014 proporcionando uma vis\xE3o 360 graus de cada cliente. Ferramentas de segmenta\xE7\xE3o permitem criar campanhas direcionadas e personalizadas. O sistema ajuda a identificar oportunidades de upsell e cross-sell, al\xE9m de gerenciar casos de suporte e satisfa\xE7\xE3o do cliente. Ao colocar o cliente no centro da opera\xE7\xE3o, o CRM permite que as equipes de atendimento e vendas ofere\xE7am um servi\xE7o proativo e de excel\xEAncia, aumentando a lealdade e o valor vital\xEDcio (LTV) da carteira.",color:e(),url:"/CRM",name:"CRM",roles:["ADMIN"],icon:"crm",type:"svg"},{shortDescription:"Gerencie todo o conte\xFAdo digital da sua empresa. Publique artigos, p\xE1ginas e m\xEDdias em seus canais web com facilidade, sem depender de desenvolvedores.",description:"O CMS (Content Management System) oferece autonomia total para as equipes de marketing e comunica\xE7\xE3o gerenciarem os portais e sites da empresa. Com um editor visual rico (WYSIWYG), \xE9 poss\xEDvel criar, editar e publicar p\xE1ginas, posts de blog e not\xEDcias em tempo real. O sistema gerencia o versionamento de conte\xFAdo, fluxos de aprova\xE7\xE3o editorial e agendamento de publica\xE7\xF5es. Possui recursos robustos de gerenciamento de m\xEDdia (imagens e v\xEDdeos) e ferramentas de SEO on-page integradas. Flex\xEDvel e escal\xE1vel, o CMS permite manter a presen\xE7a digital da marca sempre fresca e relevante, garantindo que a comunica\xE7\xE3o externa acompanhe a velocidade dos neg\xF3cios sem gargalos t\xE9cnicos.",color:e(),url:"/CMS",name:"CMS",roles:["MASTER"],icon:"cms",type:"svg"},{shortDescription:"Loja de Aplicativos",description:"Loja de Aplicativos",color:e(),url:"/Loja",name:"Loja",roles:["USER"],icon:"apps",type:"mat"}];export{o as a};
